def test_train_scaled():
    tr, te = solution.standardize([[1.0, 2.0], [3.0, 4.0]], [])
    assert tr == [[-1.0, -1.0], [1.0, 1.0]]
    assert te == []

def test_test_uses_train_stats():
    tr, te = solution.standardize([[0.0], [2.0]], [[4.0]])
    assert tr == [[-1.0], [1.0]]
    assert abs(te[0][0] - 3.0) < 1e-9

def test_zero_variance():
    tr, te = solution.standardize([[5.0], [5.0]], [[7.0]])
    assert tr == [[0.0], [0.0]]
    assert abs(te[0][0] - 2.0) < 1e-9

def test_shape_mismatch():
    try:
        solution.standardize([[1.0, 2.0]], [[1.0]])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_empty_train():
    try:
        solution.standardize([], [[1.0]])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_no_mutation():
    tr = [[1.0], [2.0]]
    te = [[3.0]]
    solution.standardize(tr, te)
    assert tr == [[1.0], [2.0]] and te == [[3.0]]
